INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',901,'{"_type":"chat:Message","id":"-5124234082:3916","threadId":"telegram:-5124234082","text":"*Baba Ganoush au four*\n\n1. Aubergines entières, piquées 2-3 fois à la fourchette. Four préchauffé grill/250°C, directement sur la grille ou plaque. ~30 min, retourner à mi-cuisson. Peau doit être noircie et chair complètement molle.\n2. Égoutter dans une passoire 10 min (évacue l''amertume).\n3. Éplucher à la main, retirer toute la peau brûlée. Égoutter encore 2-3 min.\n4. Écraser la chair (fourchette ou mixeur) avec : tahini 3 càs, jus 1 citron, 2 gousses d''ail écrasées, 2 càs huile d''olive, sel, cumin ½ càc (optionnel). Goûter, ajuster citron/sel.\n\n*Tomates rôties en même temps*\nTomates cerises 300g sur plaque, huile d''olive, pincée de sel. Four à 200°C, 20 min, jusqu''à ce qu''elles éclatent.\n→ Si le four est à 250°C pour les aubergines, mets les tomates 10 min avant de sortir les aubergines (elles cuisent plus vite à plus chaud, surveille).\n\n*Service* : baba ganoush dans un bol, creuser un puits, filet d''huile d''olive, tomates rôties dessus, persil haché.\n\nSe garde 3-4 jours au frigo sans les tomates.\n\nDame la receta en español","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"emphasis","children":[{"type":"text","value":"Baba Ganoush au four","position":{"start":{"line":1,"column":2,"offset":1},"end":{"line":1,"column":22,"offset":21}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":23,"offset":22}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":23,"offset":22}}},{"type":"list","ordered":true,"start":1,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Aubergines entières, piquées 2-3 fois à la fourchette. Four préchauffé grill/250°C, directement sur la grille ou plaque. ~30 min, retourner à mi-cuisson. Peau doit être noircie et chair complètement molle.","position":{"start":{"line":3,"column":4,"offset":27},"end":{"line":3,"column":209,"offset":232}}}],"position":{"start":{"line":3,"column":4,"offset":27},"end":{"line":3,"column":209,"offset":232}}}],"position":{"start":{"line":3,"column":1,"offset":24},"end":{"line":3,"column":209,"offset":232}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Égoutter dans une passoire 10 min (évacue l''amertume).","position":{"start":{"line":4,"column":4,"offset":236},"end":{"line":4,"column":58,"offset":290}}}],"position":{"start":{"line":4,"column":4,"offset":236},"end":{"line":4,"column":58,"offset":290}}}],"position":{"start":{"line":4,"column":1,"offset":233},"end":{"line":4,"column":58,"offset":290}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Éplucher à la main, retirer toute la peau brûlée. Égoutter encore 2-3 min.","position":{"start":{"line":5,"column":4,"offset":294},"end":{"line":5,"column":78,"offset":368}}}],"position":{"start":{"line":5,"column":4,"offset":294},"end":{"line":5,"column":78,"offset":368}}}],"position":{"start":{"line":5,"column":1,"offset":291},"end":{"line":5,"column":78,"offset":368}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Écraser la chair (fourchette ou mixeur) avec : tahini 3 càs, jus 1 citron, 2 gousses d''ail écrasées, 2 càs huile d''olive, sel, cumin ½ càc (optionnel). Goûter, ajuster citron/sel.","position":{"start":{"line":6,"column":4,"offset":372},"end":{"line":6,"column":183,"offset":551}}}],"position":{"start":{"line":6,"column":4,"offset":372},"end":{"line":6,"column":183,"offset":551}}}],"position":{"start":{"line":6,"column":1,"offset":369},"end":{"line":6,"column":183,"offset":551}}}],"position":{"start":{"line":3,"column":1,"offset":24},"end":{"line":6,"column":183,"offset":551}}},{"type":"paragraph","children":[{"type":"emphasis","children":[{"type":"text","value":"Tomates rôties en même temps","position":{"start":{"line":8,"column":2,"offset":554},"end":{"line":8,"column":30,"offset":582}}}],"position":{"start":{"line":8,"column":1,"offset":553},"end":{"line":8,"column":31,"offset":583}}},{"type":"text","value":"\nTomates cerises 300g sur plaque, huile d''olive, pincée de sel. Four à 200°C, 20 min, jusqu''à ce qu''elles éclatent.\n→ Si le four est à 250°C pour les aubergines, mets les tomates 10 min avant de sortir les aubergines (elles cuisent plus vite à plus chaud, surveille).","position":{"start":{"line":8,"column":31,"offset":583},"end":{"line":10,"column":152,"offset":850}}}],"position":{"start":{"line":8,"column":1,"offset":553},"end":{"line":10,"column":152,"offset":850}}},{"type":"paragraph","children":[{"type":"emphasis","children":[{"type":"text","value":"Service","position":{"start":{"line":12,"column":2,"offset":853},"end":{"line":12,"column":9,"offset":860}}}],"position":{"start":{"line":12,"column":1,"offset":852},"end":{"line":12,"column":10,"offset":861}}},{"type":"text","value":" : baba ganoush dans un bol, creuser un puits, filet d''huile d''olive, tomates rôties dessus, persil haché.","position":{"start":{"line":12,"column":10,"offset":861},"end":{"line":12,"column":116,"offset":967}}}],"position":{"start":{"line":12,"column":1,"offset":852},"end":{"line":12,"column":116,"offset":967}}},{"type":"paragraph","children":[{"type":"text","value":"Se garde 3-4 jours au frigo sans les tomates.","position":{"start":{"line":14,"column":1,"offset":969},"end":{"line":14,"column":46,"offset":1014}}}],"position":{"start":{"line":14,"column":1,"offset":969},"end":{"line":14,"column":46,"offset":1014}}},{"type":"paragraph","children":[{"type":"text","value":"Dame la receta en español","position":{"start":{"line":16,"column":1,"offset":1016},"end":{"line":16,"column":26,"offset":1041}}}],"position":{"start":{"li