INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',992,'{"_type":"chat:Message","id":"8641420749:117","threadId":"telegram:8641420749","text":"I''m done for today. Let''s write the daily log:\n• Reached out to Adi for JSC and open message on Slack.\n• Listened to \"Evaluer l''IA en entretien\" webinar\n• Talk to Sebastiao about Salesforce roles\n• Start working with Lenny my agent for Job Search\n• Improve the Job Search Google Sheet\n• Search for a tool to scout companies, i couldn''t find any, so I need to see if I should build it myself\n• Reach out to Romain Seraphine for exchanging tips on Job Search\n• Ask Marco Morais how he did this part of company scouting\nWhat else did I miss?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I''m done for today. Let''s write the daily log:\n• Reached out to Adi for JSC and open message on Slack.\n• Listened to \"Evaluer l''IA en entretien\" webinar\n• Talk to Sebastiao about Salesforce roles\n• Start working with Lenny my agent for Job Search\n• Improve the Job Search Google Sheet\n• Search for a tool to scout companies, i couldn''t find any, so I need to see if I should build it myself\n• Reach out to Romain Seraphine for exchanging tips on Job Search\n• Ask Marco Morais how he did this part of company scouting\nWhat else did I miss?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":22,"offset":538}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":22,"offset":538}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":10,"column":22,"offset":538}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-21T16:10:13.000Z","edited":false},"attachments":[],"isMention":false}',1793203813469);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',993,'{"_type":"chat:Message","id":"8641420749:120","threadId":"telegram:8641420749","text":"Learned:\n• difference between Forward Deployed Engineer and Deployment Specialist at Salesforce\n• Missing tools for company research/market intelligence\nTomorrow''s first action:\n• Try out Career-ops to benchmark companies\nWhat do you think?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Learned:\n• difference between Forward Deployed Engineer and Deployment Specialist at Salesforce\n• Missing tools for company research/market intelligence\nTomorrow''s first action:\n• Try out Career-ops to benchmark companies\nWhat do you think?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":19,"offset":240}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":19,"offset":240}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":19,"offset":240}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-21T16:31:23.000Z","edited":false},"attachments":[],"isMention":false}',1793205083904);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',994,'{"_type":"chat:Message","id":"8641420749:123","threadId":"telegram:8641420749","text":"I made some thoughts for next steps. Update accordingly:\n\nJob search: next steps and rationale (as of 21 Oct 2026)\n\nDecisions\n\nThe 4 CMFs are validated (ideal plus 3 backups) and fit Clément’s goals. The charter’s “CMFs tested on 3 people” gate is dropped: friendly contacts can only confirm self-fit, which is already settled.\nThe real open question is the market’s view. Specifically: how much of a stretch is the ideal CMF (hands-on Principal/Staff PM at an AI-native company), and what two-step path would make it reachable?\nPay and stretch are answered in the calibration calls. Salary reality comes from recruiters and people who have hired recently. Salary sites and desk research are weak sources for senior product roles in Madrid.\nOutreach is the bottleneck. Calls take 1–2 weeks to book. Starting outreach on 1 Nov would push the first pay data to mid-November and squeeze the 11 Dec gate.\n\nNext steps, in order\n\nLinkedIn rehab, by Thu 22 Oct.\nHeadline: one umbrella line covering the ideal and Backup 1 (Head of Product · B2B & AI-native products · Mobility & energy · Madrid from 2027).\nAbout section: 5–6 lines.\ntb.lx role: 3–5 outcome bullets, at least one on hands-on AI work.\n“Open to work” visible to recruiters only.\nWhy: the profile must be credible and consistent with the CMFs. The listening tour will reshape it anyway.\nResume, by Fri 23 Oct.\nOne master version, re-ordered from the canonical resume around the same umbrella story. No per-CMF versions yet.\nWhy: avoids perfectionism; tailoring happens per process later.\nOutreach, sent Fri 23 Oct.\n5–8 recruiters and Madrid product leaders, using the JSC recruiter template. Aim for calls in the first week of November.\nWhy: people check the profile days after accepting, so it will be ready in time.\nCompany list v0, by Sat 31 Oct, timeboxed to about 6 hours.\nAbout 30 companies across Madrid and remote EU/US employers.\nWhy: gives calibration calls something concrete to react to. Madrid-only would drop the ideal CMF, which mostly sits in the remote track. Polishing beyond v0 is the activity trap.\nIn every call, ask:\nThe three JSC questions (place me tomorrow / stretch / out of reach).\nPay ranges per CMF, as ranges for the role rather than personal pay.\nFor the ideal: “What would make me credible for a Principal PM role in an AI-native company?”\nNever reveal current pay or the floor.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I made some thoughts for next steps. Update accordingly:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":57,"offset":56}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":57,"offset":56}}},{"type":"paragraph","children":[{"type":"text","value":"Job search: next steps and rationale (as of 21 Oct 2026)","position":{"start":{"line":3,"column":1,"offset":58},"end":{"line":3,"column":57,"offset":114}}}],"position":{"start":{"line":3,"column":1,"offset":58},"end":{"line":3,"column":57,"offset":114}}},{"type":"paragraph","children":[{"type":"text","value":"Decisions","position":{"start":{"line":5,"column":1,"offset":116},"end":{"line":5,"column":10,"offset":125}}}],"position":{"start":{"line":5,"column":1,"offset":116},"end":{"line":5,"column":10,"offset":125}}},{"type":"paragraph","children":[{"type":"text","value":"The 4 CMFs are validated (ideal plus 3 backups) and fit Clément’s goals. The charter’s “CMFs tested on 3 people” gate is dropped: friendly contacts can only confirm self-fit, which is already settled.\nThe real open question is the market’s view. Specifically: how much of a stretch is the ideal CMF (hands-on Principal/Staff PM at an AI-native company), and what two-step path would make it reachable?\nPay and stretch are answered in the calibration calls. Salary reality comes from recruiters and people who have hired recently. Salary sites and desk research are weak sources for senior product roles in Madrid.\nOutreach is the bottleneck. Calls take 1–2 weeks to book. Starting outreach on 1 Nov would push the first pay data to mid-November and squeeze the 11 Dec gate.","position":{"start":{"line":7,"column":1,"offset":127},"end":{"line":10,"column":160,"offset":900}}}],"position":{"start":{"line":7,"column":1,"offset":127},"end":{"line":10,"column":160,"offset":900}}},{"type":"paragraph","children":[{"type":"text","value":"Next steps, in order","position":{"start":{"line":12,"column":1,"offset":902},"end":{"line":12,"column":21,"offset":922}}}],"position":{"start":{"line":12,"column":1,"offset":902},"end":{"line":12,"column":21,"offset":922}}},{"type":"paragraph","children":[{"type":"text","value":"LinkedIn rehab, by Thu 22 Oct.\nHeadline: one umbrella line covering the ideal and Backup 1 (Head of Product · B2B & AI-native products · Mobility & energy · Madrid from 2027).\nAbout section: 5–6 lines.\ntb.lx role: 3–5 outcome bullets, at least one on hands-on AI work.\n“Open to work” visible to recruiters only.\nWhy: the profile must be credible and consistent with the CMFs. The listening tour will reshape it anyway.\nResume, by Fri 23 Oct.\nOne master version, re-ordered from the canonical resume around the same umbrella story. No per-CMF versions yet.\nWhy: avoids perfectionism; tailoring happens per process later.\nOutreach, sent Fri 23 Oct.\n5–8 recruiters and Madrid product leaders, using the JSC recruiter template. Aim for calls in the first week of November.\nWhy: people check the profile days after accepting, so it will be ready in time.\nCompany list v0, by Sat 31 Oct, timeboxed to about 6 hours.\nAbout 30 companies across Madrid and remote EU/US employers.\nWhy: gives calibration calls something concrete to react to. Madrid-only would drop the ideal CMF, which mostly sits in the remote track. Polishing beyond v0 is the activity trap.\nIn every call, ask:\nThe three JSC questions (place me tomorrow / stretch / out of reach).\nPay ranges per CMF, as ranges for the role rather than personal pay.\nFor the ideal: “What would make me credible for a Principal PM role in an AI-native company?”\nNever reveal current pay or the floor.","position":{"start":{"line":14,"column":1,"offset":924},"end":{"line":33,"column":39,"offset":2366}}}],"position":{"start":{"line":14,"column":1,"offset":924},"end":{"line":33,"column":39,"offset":2366}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":33,"column":39,"offset":2366}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-21T16:53:44.000Z","edited":false},"attachments":[],"isMention":false}',1793206425034);
